// Two-pass separable box blur: u_pass 0 = horizontal, 1 = vertical.
// Fractional radius weights the outermost taps so animation is smooth.
vec2 dir = (u_pass == 0) ? vec2(u_texel.x, 0.0) : vec2(0.0, u_texel.y);
float r = clamp(u_radius, 0.0, 64.0);
float ri = floor(r);
float fr = r - ri;
vec4 acc = texture(u_tex, v_st);
float wsum = 1.0;
for (int i = 1; i <= 65; i++) {
  float fi = float(i);
  if (fi > ri + 1.0) break;
  float w = (fi <= ri) ? 1.0 : fr;
  if (w <= 0.0) break;
  vec2 off = dir * fi;
  acc += w * texture(u_tex, v_st + off);
  acc += w * texture(u_tex, v_st - off);
  wsum += 2.0 * w;
}
// Averaging premultiplied RGBA keeps transparent edges clean.
o = acc / wsum;
